window.ANSWER_TERMS = {"apoptose":{"title":"Apoptose","short":"Geprogrammeerde celdood: een geordend 'zelfmoordprogramma' dat de cel netjes opruimt zonder ontsteking.","definition":"<p><b>Apoptose</b> is gecontroleerde celdood. De cel krimpt, het DNA wordt in stukken geknipt en de cel valt uiteen in nette blaasjes (apoptotic bodies).</p><p>Macrofagen ruimen die op zonder ontstekingsreactie. Het is essentieel voor ontwikkeling en het verwijderen van beschadigde cellen.</p>","image_url":"","wiki_title":"Apoptosis","match":"apoptose"},"necrose":{"title":"Necrose","short":"Ongecontroleerde celdood door schade, waarbij de cel opzwelt, openbarst en een ontstekingsreactie uitlokt.","definition":"<p><b>Necrose</b> is celdood door acute schade (zuurstoftekort, toxinen, trauma). De cel zwelt op en de membraan scheurt.</p><p>De vrijkomende celinhoud lokt een ontstekingsreactie uit — anders dan bij de 'nette' apoptose.</p>","image_url":"","wiki_title":"Necrosis","match":"necrose"},"monocyt":{"title":"Monocyt","short":"Grootste witte bloedcel; verlaat het bloed en rijpt in de weefsels uit tot macrofaag of dendritische cel.","definition":"<p>De <b>monocyt</b> is de grootste circulerende leukocyt, met een niervormige kern. Hij circuleert enkele dagen en migreert dan de weefsels in.</p><p>Daar differentieert hij tot macrofaag of dendritische cel, die pathogenen fagocyteren en antigenen presenteren.</p>","image_url":"","wiki_title":"Monocyte","match":"monocyt|monocyten"},"milt":{"title":"Milt","short":"Lymfoïd orgaan dat oude bloedcellen afbreekt en bloedgedragen ziekteverwekkers filtert.","definition":"<p>De <b>milt</b> filtert het bloed: de rode pulpa ruimt versleten erytrocyten op, de witte pulpa herbergt lymfocyten voor de afweer tegen bloedgedragen pathogenen.</p><p>Ook dient de milt als bloedreservoir.</p>","image_url":"","wiki_title":"Spleen","match":"milt"},"lymfeklier":{"title":"Lymfeklier","short":"Filterstation in de lymfebaan waar antigenen worden gepresenteerd en de afweerreactie op gang komt.","definition":"<p>De <b>lymfeklier</b> filtert de lymfe en is een ontmoetingsplaats voor antigeenpresenterende cellen en lymfocyten.</p><p>Hier worden T- en B-cellen geactiveerd; bij infectie zwellen lymfeklieren op doordat de lymfocyten zich vermenigvuldigen.</p>","image_url":"","wiki_title":"Lymph node","match":"lymfeklier|lymfeklieren|lymfklier|lymfklieren"},"nodulus":{"title":"Nodulus","short":"Vaste, verheven en voelbare knobbel die dieper in de huid reikt dan een papel (> ~1 cm).","definition":"<p>Een <b>nodulus</b> (nodus, knobbel) is een stevige, verheven laesie die groter is dan een papel en dieper in de dermis of subcutis reikt.</p><p>Voorbeelden zijn een dermatofibroom of sommige huidtumoren.</p>","image_url":"","wiki_title":"Nodule (medicine)","match":"nodulus|nodus|noduli|nodi"},"urtica":{"title":"Urtica","short":"Vluchtige, jeukende, verheven zwelling van de huid — een 'galbult' of kwaddel.","definition":"<p>Een <b>urtica</b> (kwaddel, galbult) is een verheven, bleekroze zwelling door vochtophoping in de dermis, meestal sterk jeukend.</p><p>Ze ontstaat door histamine-afgifte (netelroos/urticaria) en verdwijnt doorgaans binnen 24 uur weer.</p>","image_url":"","wiki_title":"Hives","match":"urtica|urticae"},"excoriatie":{"title":"Excoriatie","short":"Oppervlakkig krab- of schaafdefect van de huid, vaak door krabben.","definition":"<p>Een <b>excoriatie</b> is een oppervlakkige beschadiging van de huid door mechanische kracht, meestal krabben.</p><p>Ze reikt tot in de bovenste dermis en gaat vaak gepaard met korstjes; typisch bij jeukende aandoeningen zoals eczeem.</p>","image_url":"","wiki_title":"Excoriation","match":"excoriatie|excoriaties"},"plaveiselcelcarcinoom":{"title":"Plaveiselcelcarcinoom","short":"Op één na meest voorkomende huidkanker, uit keratinocyten; kan uitzaaien.","definition":"<p>Het <b>plaveiselcelcarcinoom</b> gaat uit van de keratinocyten van de epidermis en is de op één na meest voorkomende huidkanker.</p><p>Anders dan het basaalcelcarcinoom kan het metastaseren. Het ontstaat vooral op zonbeschadigde huid, vaak vanuit een actinische keratose.</p>","image_url":"","wiki_title":"Squamous-cell carcinoma","match":"plaveiselcelcarcinoom|plaveiselcel carcinoom"},"radiotherapie":{"title":"Radiotherapie","short":"Behandeling met ioniserende straling die het DNA van tumorcellen beschadigt.","definition":"<p><b>Radiotherapie</b> (bestraling) gebruikt ioniserende straling om het DNA van kankercellen zodanig te beschadigen dat ze afsterven.</p><p>In de dermatologie is het een alternatief voor chirurgie bij bijvoorbeeld basaal- en plaveiselcelcarcinomen, vooral bij oudere patiënten of moeilijke locaties.</p>","image_url":"","wiki_title":"Radiation therapy","match":"radiotherapie"},"puntmutatie":{"title":"Puntmutatie","short":"Verandering van één enkele DNA-base.","definition":"<p>Een <b>puntmutatie</b> is de vervanging, invoeging of verwijdering van één enkele base in het DNA.</p><p>Afhankelijk van het effect op het codon spreekt men van een stille, missense of nonsense mutatie.</p>","image_url":"","wiki_title":"Point mutation","match":"puntmutatie"},"streptococcus pneumoniae":{"title":"Streptococcus pneumoniae","short":"De pneumokok is een grampositieve diplokok met een kapsel; de belangrijkste verwekker van pneumonie, otitis media en bacteriële meningitis.","definition":"<p><strong><em>Streptococcus pneumoniae</em></strong> (pneumokok) is een grampositieve, lancetvormige diplokok die α-hemolyse geeft op bloedagar. Het polysacharidekapsel is de belangrijkste virulentiefactor: het beschermt tegen fagocytose.</p><p>De pneumokok koloniseert de nasofarynx en is de meest voorkomende verwekker van de buiten het ziekenhuis opgelopen pneumonie, otitis media, sinusitis en bacteriële meningitis bij volwassenen. Kinderen en ouderen worden ertegen gevaccineerd.</p>","image_url":"","wiki_title":"Streptococcus pneumoniae","match":"streptococcus pneumoniae|s. pneumoniae|pneumokok|pneumokokken|streptococcus pneumoniae (pneumokok)","option_only":true},"staphylococcus aureus":{"title":"Staphylococcus aureus","short":"S. aureus is een grampositieve kok in trosjes, coagulasepositief, die huid- en wondinfecties, abcessen en ernstige systemische infecties veroorzaakt.","definition":"<p><strong><em>Staphylococcus aureus</em></strong> is een grampositieve kok die in trosjes groeit en <em>coagulase-positief</em> is (onderscheid met andere stafylokokken). Ongeveer een derde van de mensen draagt hem in de neus.</p><p>Hij veroorzaakt huid- en wekedeleninfecties (impetigo, furunkels, abcessen, wondinfecties), maar ook osteomyelitis, septische artritis, endocarditis en sepsis. Via toxines kan hij voedselvergiftiging en het toxischeshocksyndroom veroorzaken. MRSA is een methicillineresistente variant.</p>","image_url":"","wiki_title":"Staphylococcus aureus","match":"staphylococcus aureus|s. aureus|stafylococcus aureus","option_only":true},"adenovirus":{"title":"Adenovirus","short":"Adenovirussen zijn niet-omhulde DNA-virussen die verkoudheid, keelontsteking, conjunctivitis en gastro-enteritis veroorzaken.","definition":"<p><strong>Adenovirussen</strong> zijn niet-omhulde, dubbelstrengs DNA-virussen. Omdat ze geen envelop hebben, zijn ze stabiel in de omgeving en lastig te inactiveren.</p><p>Ze veroorzaken vooral bij kinderen infecties van de bovenste luchtwegen (faryngitis), conjunctivitis (o.a. faryngoconjunctivale koorts), gastro-enteritis en soms pneumonie. Ze worden ook gebruikt als vector in vaccins en gentherapie.</p>","image_url":"","wiki_title":"Adenoviridae","match":"adenovirus|adenovirussen","option_only":true},"mazelenvirus":{"title":"Mazelen(virus)","short":"Mazelen is een zeer besmettelijke virale kinderziekte met hoge koorts, hoesten, conjunctivitis en een vlekkerige huiduitslag; het virus is een omhuld RNA-virus.","definition":"<p><strong>Mazelen</strong> (morbilli) wordt veroorzaakt door het mazelenvirus, een omhuld enkelstrengs RNA-virus (paramyxovirus). Het is een van de meest besmettelijke ziekten en verspreidt zich via aerosolen.</p><p>Na een prodromale fase met koorts, hoesten, rhinitis en conjunctivitis verschijnen <em>Koplikvlekjes</em> op het wangslijmvlies en daarna een grofvlekkige rode huiduitslag die achter de oren begint. Complicaties zijn otitis, pneumonie en zeldzaam encefalitis (ook SSPE jaren later). Mazelen onderdrukt tijdelijk het immuunsysteem. Er is een vaccin (BMR).</p>","image_url":"","wiki_title":"Measles","match":"mazelenvirus|mazelen|morbilli|morbillivirus","option_only":true},"influenzavirus":{"title":"Influenza(virus)","short":"Influenza (griep) wordt veroorzaakt door het influenzavirus, een omhuld RNA-virus met hoge koorts, spierpijn en hoesten; jaarlijks seizoensgebonden.","definition":"<p><strong>Influenza</strong> wordt veroorzaakt door influenzavirussen (type A, B en C), omhulde RNA-virussen met een gesegmenteerd genoom. Op het oppervlak zitten hemagglutinine (H) en neuraminidase (N).</p><p>Kleine mutaties in H en N (<em>antigene drift</em>) veroorzaken de jaarlijkse griepepidemie; uitwisseling van gensegmenten (<em>antigene shift</em>, alleen type A) kan pandemieën geven. Klachten: plotselinge hoge koorts, spierpijn, hoofdpijn, droge hoest. Complicatie is o.a. een secundaire bacteriële pneumonie. Jaarlijks vaccin voor risicogroepen.</p>","image_url":"","wiki_title":"Influenza","match":"influenzavirus|influenza|griep|influenza a|influenzavirussen","option_only":true},"rode hond":{"title":"Rode hond (rubella)","short":"Rode hond is een milde virale ziekte met huiduitslag en zwollen klieren, maar bij infectie in de vroege zwangerschap ontstaat het congenitaal rubellasyndroom.","definition":"<p><strong>Rode hond</strong> (rubella) wordt veroorzaakt door het rubellavirus, een omhuld RNA-virus. Bij kinderen verloopt het mild: lichte koorts, kleinvlekkige huiduitslag en gezwollen lymfeklieren (o.a. achter de oren en in de nek).</p><p>Gevaarlijk is infectie van een zwangere in het eerste trimester: het virus kan de foetus besmetten en het <em>congenitaal rubellasyndroom</em> veroorzaken (doofheid, cataract, hartafwijkingen). Vaccinatie gebeurt met het BMR-vaccin.</p>","image_url":"","wiki_title":"Rubella","match":"rode hond|rubella|rubellavirus","option_only":true},"norovirus":{"title":"Norovirus","short":"Norovirus is een zeer besmettelijk RNA-virus dat acute gastro-enteritis veroorzaakt met plotseling braken en diarree, vaak in uitbraken.","definition":"<p>Het <strong>norovirus</strong> is een niet-omhuld RNA-virus (calicivirus). Er zijn maar weinig deeltjes nodig voor infectie en het overleeft lang in de omgeving.</p><p>Het veroorzaakt acute gastro-enteritis met plotseling braken, waterige diarree en buikkrampen, die 1 à 3 dagen duurt. Uitbraken komen vooral voor in verpleeghuizen, ziekenhuizen en op cruiseschepen; handhygiëne is de belangrijkste maatregel.</p>","image_url":"","wiki_title":"Norovirus","match":"norovirus|noro","option_only":true},"proliferatie":{"title":"Proliferatie","short":"Proliferatie is de toename van het aantal cellen door celdeling.","definition":"<p><strong>Proliferatie</strong> is vermeerdering van cellen door celdeling (mitose). Het is een basisproces bij groei en ontwikkeling, weefselherstel en vernieuwing van bijvoorbeeld huid, darmepitheel en bloedcellen.</p><p>Proliferatie wordt gereguleerd door groeifactoren en de celcyclus-controlepunten. Ongecontroleerde proliferatie is een kenmerk van kanker.</p>","image_url":"","wiki_title":"","match":"proliferatie|celproliferatie","option_only":true},"differentiatie":{"title":"Differentiatie","short":"Differentiatie is het proces waarbij een minder gespecialiseerde cel een gespecialiseerde vorm en functie krijgt.","definition":"<p>Bij <strong>(cel)differentiatie</strong> zet een cel bepaalde genen aan en andere uit, waardoor ze een specifieke structuur en functie krijgt — bijvoorbeeld een stamcel die een neuron, spiercel of rode bloedcel wordt.</p><p>Differentiatie wordt gestuurd door signalen uit de omgeving (groeifactoren, cel-celcontact) en transcriptiefactoren. In tumoren geeft de mate van differentiatie (goed tot slecht gedifferentieerd) informatie over agressiviteit.</p>","image_url":"","wiki_title":"","match":"differentiatie|celdifferentiatie","option_only":true},"artrose (osteoarthritis)":{"title":"Artrose","short":"Artrose is degeneratie van gewrichtskraakbeen met botreactie; het geeft startpijn en pijn bij belasting, vooral in knieën, heupen en handen bij ouderen.","definition":"<p>Bij <strong>artrose</strong> slijt en verdwijnt het gewrichtskraakbeen, met reactieve veranderingen van het bot: <em>osteofyten</em>, subchondrale sclerose en cysten, en versmalling van de gewrichtsspleet op de röntgenfoto.</p><p>Risicofactoren: leeftijd, overgewicht, eerder letsel en aanleg. Klachten: pijn bij belasting, startpijn en korte ochtendstijfheid (&lt;30 minuten), soms crepitaties en verminderde beweeglijkheid. Typische plaatsen: knie, heup, DIP- en PIP-gewrichten (Heberden- en Bouchardknobbels) en het CMC-1-gewricht.</p>","image_url":"","wiki_title":"Osteoarthritis","match":"artrose (osteoarthritis)|artrose|osteoarthritis|osteoartrose","option_only":true},"maagcarcinoom":{"title":"Maagcarcinoom","short":"Een maagcarcinoom is een kwaadaardige tumor (meestal adenocarcinoom) van de maag; risicofactoren zijn o.a. H. pylori, roken en zoutrijke voeding.","definition":"<p>Het <strong>maagcarcinoom</strong> is meestal een adenocarcinoom, uitgaand van het klierepitheel. Het intestinale type ontstaat via een reeks van chronische (H. pylori-)gastritis, atrofie, intestinale metaplasie en dysplasie; het diffuse type (zegelringcellen) infiltreert de wand zonder duidelijke massa (linitis plastica).</p><p>Klachten komen vaak laat: verminderde eetlust, vroege verzadiging, gewichtsverlies, epigastrische pijn, anemie of slikklachten. Metastasen kunnen zich manifesteren als een klier van Virchow (links supraclaviculair) of ovariummetastasen (Krukenberg).</p>","image_url":"","wiki_title":"Stomach cancer","match":"maagcarcinoom|maagkanker|adenocarcinoom van de maag","option_only":true},"diarree":{"title":"Diarree","short":"Diarree is het vaker dan normaal (≥3x per dag) produceren van brijige tot waterdunne ontlasting.","definition":"<p><strong>Diarree</strong> betekent een verhoogde frequentie (meestal ≥3 keer per dag) en verminderde consistentie van de ontlasting. Acute diarree (&lt;2 weken) is meestal infectieus (virussen zoals norovirus, bacteriën, parasieten).</p><p>Mechanismen: <em>secretoir</em> (bijv. door toxines zoals choleratoxine), <em>osmotisch</em> (bijv. lactose-intolerantie, laxantia), <em>inflammatoir</em> (bijv. IBD, invasieve bacteriën, met bloed en slijm) en versnelde motiliteit. Het belangrijkste risico is uitdroging en elektrolytverlies.</p>","image_url":"","wiki_title":"Diarrhea","match":"diarree","option_only":true},"koorts":{"title":"Koorts","short":"Koorts is een verhoogde lichaamstemperatuur (≥38,0 °C) doordat de hypothalamus het setpoint hoger instelt, meestal als reactie op infectie.","definition":"<p>Bij <strong>koorts</strong> wordt het temperatuursetpoint in de hypothalamus verhoogd. Pyrogenen zoals bacteriële producten en cytokines (IL-1, IL-6, TNF) stimuleren daar de productie van prostaglandine E<sub>2</sub>.</p><p>Het lichaam ervaart de normale temperatuur dan als te koud: vasoconstrictie en rillingen verhogen de temperatuur. Als het setpoint weer daalt, volgen zweten en vasodilatatie. Koortsremmers (paracetamol, NSAID's) remmen de prostaglandinesynthese. Hyperthermie (bijv. hitteberoerte) is iets anders: daar is het setpoint níet verhoogd.</p>","image_url":"","wiki_title":"Fever","match":"koorts|febris|pyrexie|hoge koorts","option_only":true},"onafhankelijke t-toets":{"title":"Onafhankelijke t-toets","short":"De onafhankelijke t-toets vergelijkt de gemiddelden van een continue, normaal verdeelde variabele tussen twee onafhankelijke groepen.","definition":"<p>De <strong>onafhankelijke (ongepaarde) t-toets</strong> toetst of het gemiddelde van een continue uitkomst verschilt tussen twee groepen die niets met elkaar te maken hebben, bijvoorbeeld de bloeddruk in een behandel- en een controlegroep.</p><p>Voorwaarden: de uitkomst is (ongeveer) normaal verdeeld in beide groepen, de waarnemingen zijn onafhankelijk en de varianties zijn ongeveer gelijk (anders de Welch-variant). Bij metingen bij dezelfde personen gebruik je de gepaarde t-toets; bij scheve data een non-parametrische toets (Mann-Whitney).</p>","image_url":"","wiki_title":"Student's t-test","match":"onafhankelijke t-toets|ongepaarde t-toets|independent samples t-test|t-toets voor onafhankelijke steekproeven","option_only":true},"creatinine":{"title":"Creatinine","short":"Creatinine is een afbraakproduct van creatinefosfaat uit spieren; de bloedwaarde wordt gebruikt om de nierfunctie te schatten.","definition":"<p><strong>Creatinine</strong> ontstaat in een vrij constant tempo uit creatine in spieren en wordt vooral door glomerulaire filtratie uitgescheiden. Daarom stijgt de serumwaarde als de nierfunctie (GFR) daalt; op basis van creatinine, leeftijd en geslacht wordt de eGFR berekend. Spiermassa beïnvloedt de waarde: bij weinig spiermassa kan een normaal creatinine een verminderde nierfunctie maskeren.</p>","image_url":"","wiki_title":"Creatinine","match":"creatinine|kreatinine|serumcreatinine","option_only":true},"campylobacter jejuni":{"title":"Campylobacter jejuni","short":"Campylobacter jejuni is een gekromde gramnegatieve staaf en een belangrijke oorzaak van bacteriële gastro-enteritis, vaak via kip.","definition":"<p><strong><em>Campylobacter jejuni</em></strong> wordt opgelopen via onvoldoende verhit gevogelte, rauwe melk of besmet water. Het geeft koorts, buikkrampen en (soms bloederige) diarree. Een bekende late complicatie is het syndroom van Guillain-Barré, door kruisreactie van antistoffen met gangliosiden in zenuwen; ook reactieve artritis komt voor.</p>","image_url":"","wiki_title":"Campylobacter jejuni","match":"campylobacter jejuni|campylobacter","option_only":true},"yersinia enterocolitica":{"title":"Yersinia enterocolitica","short":"Yersinia enterocolitica is een gramnegatieve staaf die via varkensvlees een enterocolitis kan veroorzaken die appendicitis kan nabootsen.","definition":"<p><strong><em>Yersinia enterocolitica</em></strong> groeit ook bij lage temperatuur. Infectie geeft koorts, diarree en buikpijn; door ontsteking van het terminale ileum en de mesenteriale lymfeklieren kan het beeld lijken op appendicitis (pseudo-appendicitis). Na infectie kunnen reactieve artritis en erythema nodosum ontstaan, vooral bij HLA-B27-dragers. IJzerstapeling (hemochromatose) is een risicofactor voor ernstige infectie.</p>","image_url":"","wiki_title":"Yersinia enterocolitica","match":"yersinia enterocolitica|yersinia","option_only":true},"treponema pallidum":{"title":"Treponema pallidum","short":"Treponema pallidum is de spirocheet die syfilis veroorzaakt.","definition":"<p><strong><em>Treponema pallidum</em></strong> is een dunne, spiraalvormige bacterie die niet te kweken is en niet zichtbaar is met een gramkleuring. Ze wordt seksueel en via de placenta overgedragen. Diagnostiek gebeurt meestal serologisch (treponemale en non-treponemale tests) of met PCR uit een ulcus. Penicilline blijft het middel van keus.</p>","image_url":"","wiki_title":"Treponema pallidum","match":"treponema pallidum|treponema","option_only":true},"herpes simplexvirus":{"title":"Herpes simplexvirus (HSV)","short":"Het herpes simplexvirus veroorzaakt blaasjes op huid en slijmvliezen en blijft daarna latent in sensibele ganglia.","definition":"<p>Er zijn twee typen: <strong>HSV-1</strong> (vooral oraal, koortslip, gingivostomatitis) en <strong>HSV-2</strong> (vooral genitaal), al overlappen ze. Na de primaire infectie blijft het virus latent in sensibele ganglia en kan het reactiveren. Ernstige vormen zijn herpesencefalitis, keratitis, eczema herpeticum en neonatale herpes. Behandeling met (val)aciclovir.</p>","image_url":"","wiki_title":"Herpes simplex virus","match":"herpes simplexvirus|herpes simplex|hsv|hsv-1|hsv-2","option_only":true},"appendicitis":{"title":"Appendicitis","short":"Appendicitis is een ontsteking van de appendix, met buikpijn die vaak rond de navel begint en naar rechtsonder trekt.","definition":"<p>Bij <strong>appendicitis</strong> raakt het lumen van de appendix afgesloten (bijv. door een fecoliet of lymfoïde hyperplasie), waarna ontsteking en infectie volgen. Klachten: pijn eerst rond de navel, later rechtsonder (McBurney), misselijkheid, koorts en lokale peritoneale prikkeling. Zonder behandeling kan perforatie optreden. Diagnose met echo en/of CT; behandeling meestal appendectomie.</p>","image_url":"","wiki_title":"Appendicitis","match":"appendicitis|blindedarmontsteking","option_only":true},"coloncarcinoom":{"title":"Coloncarcinoom (darmkanker)","short":"Coloncarcinoom is een kwaadaardige tumor van de dikke darm, meestal een adenocarcinoom dat ontstaat uit een poliep.","definition":"<p>Het <strong>colorectaal carcinoom</strong> ontstaat meestal via de adenoom-carcinoomsequentie, waarbij mutaties (o.a. in APC, KRAS, p53) zich opstapelen. Risicofactoren zijn leeftijd, familiaire belasting (FAP, Lynch-syndroom), IBD, rood en bewerkt vlees, alcohol en roken. Klachten: veranderd ontlastingspatroon, bloed bij de ontlasting en ijzergebreksanemie. In Nederland is er een bevolkingsonderzoek met de FIT-test.</p>","image_url":"","wiki_title":"Colorectal cancer","match":"coloncarcinoom|darmkanker|colorectaal carcinoom|dikkedarmkanker","option_only":true},"gastroenteritis":{"title":"Gastro-enteritis","short":"Gastro-enteritis is een ontsteking van maag en darm, meestal door een virus, met braken en diarree.","definition":"<p>Acute <strong>gastro-enteritis</strong> wordt meestal veroorzaakt door virussen (norovirus, rotavirus), soms door bacteriën (<em>Campylobacter</em>, <em>Salmonella</em>) of parasieten. Het belangrijkste risico is uitdroging, vooral bij jonge kinderen en ouderen. Behandeling bestaat vooral uit orale rehydratie; antibiotica zijn zelden nodig.</p>","image_url":"","wiki_title":"Gastroenteritis","match":"gastroenteritis|gastro-enteritis|buikgriep","option_only":true},"hemochromatose":{"title":"Hemochromatose","short":"Hemochromatose is een erfelijke ijzerstapelingsziekte waarbij te veel ijzer uit de darm wordt opgenomen.","definition":"<p>Bij <strong>hereditaire hemochromatose</strong> (meestal homozygotie voor de C282Y-mutatie in het HFE-gen) is er te weinig hepcidine, waardoor ijzer ongeremd wordt opgenomen. IJzer stapelt in lever, pancreas, hart, gewrichten en huid, met leverfibrose of -cirrose, diabetes, cardiomyopathie, artropathie en een bronzen huid. De transferrineverzadiging en het ferritine zijn verhoogd; behandeling met aderlatingen.</p>","image_url":"","wiki_title":"Hemochromatosis","match":"hemochromatose|hereditaire hemochromatose|ijzerstapeling","option_only":true},"reumatoïde artritis":{"title":"Reumatoïde artritis","short":"Reumatoïde artritis is een chronische auto-immuunziekte met symmetrische ontsteking van vooral de kleine gewrichten van handen en voeten.","definition":"<p>Bij <strong>reumatoïde artritis</strong> leidt synovitis tot pannusvorming en erosie van kraakbeen en bot. Kenmerken: symmetrische polyartritis van MCP-, PIP- en MTP-gewrichten, ochtendstijfheid langer dan een uur, reumafactor en anti-CCP-antistoffen. Extra-articulair: reumanoduli, longaandoeningen, vasculitis. Vroege behandeling met DMARD's (zoals methotrexaat) voorkomt gewrichtsschade.</p>","image_url":"","wiki_title":"Rheumatoid arthritis","match":"reumatoïde artritis|reumatoide artritis|reumatoïde arthritis","option_only":true},"jicht":{"title":"Jicht","short":"Jicht is een gewrichtsontsteking door neerslag van uraatkristallen bij een verhoogd urinezuur.","definition":"<p>Bij <strong>jicht</strong> slaan mononatriumuraatkristallen neer in en rond gewrichten. Een aanval begint plotseling, vaak ’s nachts, met een rood, gezwollen, zeer pijnlijk gewricht. Uitlokkers zijn alcohol, purinerijk voedsel, diuretica en uitdroging. In het gewrichtsvocht zijn naaldvormige, negatief dubbelbrekende kristallen te zien. Behandeling van een aanval met NSAID's, colchicine of corticosteroïden; preventie met allopurinol.</p>","image_url":"","wiki_title":"Gout","match":"jicht|arthritis urica|podagra","option_only":true},"mammacarcinoom":{"title":"Mammacarcinoom (borstkanker)","short":"Het mammacarcinoom is een kwaadaardige tumor van de borstklier, de meest voorkomende kanker bij vrouwen.","definition":"<p>Het <strong>mammacarcinoom</strong> is meestal een invasief carcinoom uitgaande van de afvoergangen (ductaal) of lobjes (lobulair). Risicofactoren zijn leeftijd, familiaire belasting (BRCA1/2), lange oestrogeenblootstelling en alcohol. Behandeling hangt af van stadium en receptorstatus (oestrogeen, progesteron, HER2): chirurgie, radiotherapie, hormonale therapie, chemotherapie en doelgerichte therapie. Er is een bevolkingsonderzoek met mammografie.</p>","image_url":"","wiki_title":"Breast cancer","match":"mammacarcinoom|borstkanker","option_only":true},"adenocarcinoom":{"title":"Adenocarcinoom","short":"Een adenocarcinoom is een kwaadaardige tumor van klierepitheel, zoals in darm, borst, prostaat, long en pancreas.","definition":"<p>Een <strong>adenocarcinoom</strong> vormt (verwaarloosde) klierstructuren of maakt slijm. Het is de meest voorkomende vorm van kanker van colon, maag, pancreas, prostaat, borst en een groot deel van het longcarcinoom. De mate van differentiatie (graad) en het stadium bepalen de prognose.</p>","image_url":"","wiki_title":"Adenocarcinoma","match":"adenocarcinoom|adenocarcinomen","option_only":true},"diverticulitis":{"title":"Diverticulitis","short":"Diverticulitis is een ontsteking van een of meer divertikels (uitstulpingen) van de dikke darm.","definition":"<p>Bij <b>diverticulitis</b> raakt een divertikel ontstoken, vermoedelijk door obstructie en microperforatie. Divertikels ontstaan vooral bij ouderen en bij vezelarme voeding. De ernst wordt ingedeeld volgens Hinchey (van lokale ontsteking tot abces en perforatie met peritonitis). Diagnose met echo of CT; ongecompliceerde gevallen worden meestal conservatief behandeld.</p>","image_url":"","wiki_title":"Diverticulitis","match":"diverticulitis","option_only":true},"trichomonas":{"title":"Trichomonas vaginalis","short":"Trichomonas vaginalis is een seksueel overdraagbare protozo die vaginitis met schuimende, groengele afscheiding veroorzaakt.","definition":"<p><strong>Trichomoniasis</strong> geeft bij vrouwen jeuk, branderigheid en riekende, schuimende afscheiding, soms met een ‘aardbeiencervix’; bij mannen meestal geen klachten. De beweeglijke flagellaten zijn soms te zien in een nat preparaat; PCR is gevoeliger. Behandeling met metronidazol, ook voor de partner.</p>","image_url":"","wiki_title":"Trichomoniasis","match":"trichomonas|trichomonas vaginalis|trichomoniasis","option_only":true},"appendicitis acuta":{"title":"Appendicitis","short":"Appendicitis is een ontsteking van de appendix, met buikpijn die vaak rond de navel begint en naar rechtsonder trekt.","definition":"<p>Bij <strong>appendicitis</strong> raakt het lumen van de appendix afgesloten (bijv. door een fecoliet of lymfoïde hyperplasie), waarna ontsteking en infectie volgen. Klachten: pijn eerst rond de navel, later rechtsonder (McBurney), misselijkheid, koorts en lokale peritoneale prikkeling. Zonder behandeling kan perforatie optreden. Diagnose met echo en/of CT; behandeling meestal appendectomie.</p>","image_url":"","wiki_title":"Appendicitis","match":"appendicitis acuta","option_only":true},"streptococcus pneumoniae (pneumokok)":{"title":"Streptococcus pneumoniae","short":"De pneumokok is een grampositieve diplokok met een kapsel; de belangrijkste verwekker van pneumonie, otitis media en bacteriële meningitis.","definition":"<p><strong><em>Streptococcus pneumoniae</em></strong> (pneumokok) is een grampositieve, lancetvormige diplokok die α-hemolyse geeft op bloedagar. Het polysacharidekapsel is de belangrijkste virulentiefactor: het beschermt tegen fagocytose.</p><p>De pneumokok koloniseert de nasofarynx en is de meest voorkomende verwekker van de buiten het ziekenhuis opgelopen pneumonie, otitis media, sinusitis en bacteriële meningitis bij volwassenen. Kinderen en ouderen worden ertegen gevaccineerd.</p>","image_url":"","wiki_title":"Streptococcus pneumoniae","match":"streptococcus pneumoniae (pneumokok)","option_only":true},"hoge koorts":{"title":"Koorts","short":"Koorts is een verhoogde lichaamstemperatuur (≥38,0 °C) doordat de hypothalamus het setpoint hoger instelt, meestal als reactie op infectie.","definition":"<p>Bij <strong>koorts</strong> wordt het temperatuursetpoint in de hypothalamus verhoogd. Pyrogenen zoals bacteriële producten en cytokines (IL-1, IL-6, TNF) stimuleren daar de productie van prostaglandine E<sub>2</sub>.</p><p>Het lichaam ervaart de normale temperatuur dan als te koud: vasoconstrictie en rillingen verhogen de temperatuur. Als het setpoint weer daalt, volgen zweten en vasodilatatie. Koortsremmers (paracetamol, NSAID's) remmen de prostaglandinesynthese. Hyperthermie (bijv. hitteberoerte) is iets anders: daar is het setpoint níet verhoogd.</p>","image_url":"","wiki_title":"Fever","match":"hoge koorts","option_only":true},"salmonella spp":{"title":"Salmonella","short":"Salmonella zijn gramnegatieve staven die voedselinfecties (gastro-enteritis) en buiktyfus kunnen veroorzaken.","definition":"<p>Niet-tyfeuze <strong>salmonellae</strong> komen via onvoldoende verhit voedsel (kip, eieren) binnen en geven koorts, buikkrampen en diarree. <em>S. typhi</em> en <em>S. paratyphi</em> veroorzaken (para)tyfus, een systemische ziekte met hoge koorts, relatieve bradycardie en roseola. Bij sikkelcelziekte kan Salmonella osteomyelitis veroorzaken.</p>","image_url":"","wiki_title":"Salmonella","match":"salmonella spp|salmonella|salmonellosis","option_only":true},"shigella spp":{"title":"Shigella","short":"Shigella is een gramnegatieve staaf die al bij een zeer kleine infectiedosis bloederige diarree (bacillaire dysenterie) veroorzaakt.","definition":"<p><strong>Shigella</strong> dringt het colonepitheel binnen en verspreidt zich van cel tot cel, met ulceraties, koorts, buikkrampen en bloederig-slijmerige diarree. <em>S. dysenteriae</em> type 1 maakt shigatoxine (risico op HUS). Overdracht fecaal-oraal, ook seksueel. Behandeling met antibiotica bij ernstige gevallen.</p>","image_url":"","wiki_title":"Shigellosis","match":"shigella spp|shigella|shigellose|bacillaire dysenterie|shigella dysenteriae","option_only":true},"reumatoide artritis":{"title":"Reumatoïde artritis","short":"Reumatoïde artritis is een chronische auto-immuunziekte met symmetrische ontsteking van vooral de kleine gewrichten van handen en voeten.","definition":"<p>Bij <strong>reumatoïde artritis</strong> leidt synovitis tot pannusvorming en erosie van kraakbeen en bot. Kenmerken: symmetrische polyartritis van MCP-, PIP- en MTP-gewrichten, ochtendstijfheid langer dan een uur, reumafactor en anti-CCP-antistoffen. Extra-articulair: reumanoduli, longaandoeningen, vasculitis. Vroege behandeling met DMARD's (zoals methotrexaat) voorkomt gewrichtsschade.</p>","image_url":"","wiki_title":"Rheumatoid arthritis","match":"reumatoide artritis","option_only":true},"s. pneumoniae":{"title":"Streptococcus pneumoniae","short":"De pneumokok is een grampositieve diplokok met een kapsel; de belangrijkste verwekker van pneumonie, otitis media en bacteriële meningitis.","definition":"<p><strong><em>Streptococcus pneumoniae</em></strong> (pneumokok) is een grampositieve, lancetvormige diplokok die α-hemolyse geeft op bloedagar. Het polysacharidekapsel is de belangrijkste virulentiefactor: het beschermt tegen fagocytose.</p><p>De pneumokok koloniseert de nasofarynx en is de meest voorkomende verwekker van de buiten het ziekenhuis opgelopen pneumonie, otitis media, sinusitis en bacteriële meningitis bij volwassenen. Kinderen en ouderen worden ertegen gevaccineerd.</p>","image_url":"","wiki_title":"Streptococcus pneumoniae","match":"s. pneumoniae","option_only":true},"s. aureus":{"title":"Staphylococcus aureus","short":"S. aureus is een grampositieve kok in trosjes, coagulasepositief, die huid- en wondinfecties, abcessen en ernstige systemische infecties veroorzaakt.","definition":"<p><strong><em>Staphylococcus aureus</em></strong> is een grampositieve kok die in trosjes groeit en <em>coagulase-positief</em> is (onderscheid met andere stafylokokken). Ongeveer een derde van de mensen draagt hem in de neus.</p><p>Hij veroorzaakt huid- en wekedeleninfecties (impetigo, furunkels, abcessen, wondinfecties), maar ook osteomyelitis, septische artritis, endocarditis en sepsis. Via toxines kan hij voedselvergiftiging en het toxischeshocksyndroom veroorzaken. MRSA is een methicillineresistente variant.</p>","image_url":"","wiki_title":"Staphylococcus aureus","match":"s. aureus","option_only":true},"jicht (artritis urica)":{"title":"Jicht","short":"Jicht is een gewrichtsontsteking door neerslag van uraatkristallen bij een verhoogd urinezuur.","definition":"<p>Bij <strong>jicht</strong> slaan mononatriumuraatkristallen neer in en rond gewrichten. Een aanval begint plotseling, vaak ’s nachts, met een rood, gezwollen, zeer pijnlijk gewricht. Uitlokkers zijn alcohol, purinerijk voedsel, diuretica en uitdroging. In het gewrichtsvocht zijn naaldvormige, negatief dubbelbrekende kristallen te zien. Behandeling van een aanval met NSAID's, colchicine of corticosteroïden; preventie met allopurinol.</p>","image_url":"","wiki_title":"Gout","match":"jicht (artritis urica)","option_only":true},"diverticultis":{"title":"Diverticulitis","short":"Diverticulitis is een ontsteking van een of meer divertikels (uitstulpingen) van de dikke darm.","definition":"<p>Bij <b>diverticulitis</b> raakt een divertikel ontstoken, vermoedelijk door obstructie en microperforatie. Divertikels ontstaan vooral bij ouderen en bij vezelarme voeding. De ernst wordt ingedeeld volgens Hinchey (van lokale ontsteking tot abces en perforatie met peritonitis). Diagnose met echo of CT; ongecompliceerde gevallen worden meestal conservatief behandeld.</p>","image_url":"","wiki_title":"Diverticulitis","match":"diverticultis","option_only":true},"selectiebias":{"title":"Selectiebias","short":"Selectiebias ontstaat als de manier waarop deelnemers in een onderzoek terechtkomen samenhangt met zowel blootstelling als uitkomst.","definition":"<p>Voorbeelden van <strong>selectiebias</strong> zijn het gebruik van ziekenhuiscontroles in een patiënt-controleonderzoek, selectieve uitval tijdens follow-up en het ‘healthy worker effect’. Anders dan confounding kan selectiebias achteraf niet worden gecorrigeerd.</p>","image_url":"","wiki_title":"Selection bias","match":"selectiebias|selectievertekening","option_only":true},"jichtartritis":{"title":"Jicht","short":"Jicht is een gewrichtsontsteking door neerslag van uraatkristallen bij een verhoogd urinezuur.","definition":"<p>Bij <strong>jicht</strong> slaan mononatriumuraatkristallen neer in en rond gewrichten. Een aanval begint plotseling, vaak ’s nachts, met een rood, gezwollen, zeer pijnlijk gewricht. Uitlokkers zijn alcohol, purinerijk voedsel, diuretica en uitdroging. In het gewrichtsvocht zijn naaldvormige, negatief dubbelbrekende kristallen te zien. Behandeling van een aanval met NSAID's, colchicine of corticosteroïden; preventie met allopurinol.</p>","image_url":"","wiki_title":"Gout","match":"jichtartritis","option_only":true},"pneumonie door pneumokokken":{"title":"Streptococcus pneumoniae","short":"De pneumokok is een grampositieve diplokok met een kapsel; de belangrijkste verwekker van pneumonie, otitis media en bacteriële meningitis.","definition":"<p><strong><em>Streptococcus pneumoniae</em></strong> (pneumokok) is een grampositieve, lancetvormige diplokok die α-hemolyse geeft op bloedagar. Het polysacharidekapsel is de belangrijkste virulentiefactor: het beschermt tegen fagocytose.</p><p>De pneumokok koloniseert de nasofarynx en is de meest voorkomende verwekker van de buiten het ziekenhuis opgelopen pneumonie, otitis media, sinusitis en bacteriële meningitis bij volwassenen. Kinderen en ouderen worden ertegen gevaccineerd.</p>","image_url":"","wiki_title":"Streptococcus pneumoniae","match":"pneumonie door pneumokokken","option_only":true},"campylobacter spp":{"title":"Campylobacter jejuni","short":"Campylobacter jejuni is een gekromde gramnegatieve staaf en een belangrijke oorzaak van bacteriële gastro-enteritis, vaak via kip.","definition":"<p><strong><em>Campylobacter jejuni</em></strong> wordt opgelopen via onvoldoende verhit gevogelte, rauwe melk of besmet water. Het geeft koorts, buikkrampen en (soms bloederige) diarree. Een bekende late complicatie is het syndroom van Guillain-Barré, door kruisreactie van antistoffen met gangliosiden in zenuwen; ook reactieve artritis komt voor.</p>","image_url":"","wiki_title":"Campylobacter jejuni","match":"campylobacter spp","option_only":true},"adenovirusinfectie":{"title":"Adenovirus","short":"Adenovirussen zijn niet-omhulde DNA-virussen die verkoudheid, keelontsteking, conjunctivitis en gastro-enteritis veroorzaken.","definition":"<p><strong>Adenovirussen</strong> zijn niet-omhulde, dubbelstrengs DNA-virussen. Omdat ze geen envelop hebben, zijn ze stabiel in de omgeving en lastig te inactiveren.</p><p>Ze veroorzaken vooral bij kinderen infecties van de bovenste luchtwegen (faryngitis), conjunctivitis (o.a. faryngoconjunctivale koorts), gastro-enteritis en soms pneumonie. Ze worden ook gebruikt als vector in vaccins en gentherapie.</p>","image_url":"","wiki_title":"Adenoviridae","match":"adenovirusinfectie","option_only":true},"humaan papilloma virus":{"title":"Humaan papillomavirus (HPV)","short":"HPV is een DNA-virus dat wratten veroorzaakt; hoog-risicotypes (o.a. 16 en 18) veroorzaken baarmoederhalskanker en andere kankers.","definition":"<p>Het <strong>humaan papillomavirus</strong> infecteert basale cellen van huid en slijmvlies. Laag-risicotypes (6, 11) geven wratten en condylomata acuminata. Hoog-risicotypes maken de eiwitten E6 en E7, die p53 en Rb uitschakelen; persisterende infectie kan leiden tot cervixcarcinoom en kankers van anus, vulva, penis en orofarynx. Er is een vaccin en een bevolkingsonderzoek met hrHPV-test.</p>","image_url":"","wiki_title":"Human papillomavirus infection","match":"humaan papilloma virus","option_only":true},"kleincellig longcarcinoom":{"title":"Kleincellig longcarcinoom (SCLC)","short":"Een agressief, snelgroeiend type longkanker dat vroeg metastaseert en sterk samenhangt met roken.","definition":"<p>Reageert aanvankelijk goed op chemotherapie maar recidiveert vaak.</p>","image_url":"","wiki_title":"Small-cell carcinoma","match":"kleincellig longcarcinoom","option_only":true},"confounding":{"title":"Confounding","short":"Vertekening van een verband doordat een derde factor zowel met de determinant als met de uitkomst samenhangt.","definition":"<p><b>Confounding</b> is de vertekening van het verband tussen determinant en uitkomst door een verstorende variabele (confounder) die met beide samenhangt en niet in het causale pad ligt. In de multivitamine-casus is de ongezondere leefstijl de confounder.</p>","image_url":"","wiki_title":"Confounding","match":"confounding","option_only":true},"effectmodificatie":{"title":"effectmodificatie","short":"Effectmodificatie betekent dat het effect van de blootstelling verschilt tussen strata van een derde variabele.","definition":"<p><b>Effectmodificatie</b> (interactie) treedt op als de effectmaat verschilt per stratum van een andere variabele. In tegenstelling tot confounding is het een reëel fenomeen dat je per stratum rapporteert.</p>","image_url":"","wiki_title":"","match":"effectmodificatie","option_only":true},"proportional hazards":{"title":"Proportional hazards-assumptie","short":"De aanname in Cox-regressie dat de hazard ratio tussen groepen constant is over de hele follow-up.","definition":"<p>De <b>proportional hazards-assumptie</b> houdt in dat het relatieve effect (hazard ratio) constant blijft over de tijd. Ze kan getoetst worden met een tijdsafhankelijke covariaat (interactie met de tijd); een significante interactieterm wijst op schending.</p>","image_url":"","wiki_title":"","match":"proportional hazards","option_only":true},"uroflowmetrie":{"title":"Uroflowmetrie","short":"Bij uroflowmetrie plast de patiënt in een meettoestel dat de urinestraal in ml per seconde registreert.","definition":"<p>Een lage maximale flow met een afgevlakte curve wijst op een obstructie (bijv. prostaatvergroting of urethrastrictuur) of een zwakke blaasspier. Samen met het residu (bladderscan) helpt <strong>uroflowmetrie</strong> bij mictieklachten.</p>","image_url":"","wiki_title":"Uroflowmetry","match":"uroflowmetrie|flowmeting","option_only":true},"urine dipstick":{"title":"Urinestick","short":"Een urinestick test met kleurveldjes op o.a. nitriet, leukocyten, bloed, eiwit en glucose in de urine.","definition":"<p>Bij verdenking op een urineweginfectie is een positieve nitriettest specifiek. Een positieve test op leukocyten of erytrocyten is minder specifiek. Bij twijfel volgt een sediment of een kweek.</p>","image_url":"","wiki_title":"Urine test strip","match":"urine dipstick|urinestick|stickonderzoek","option_only":true},"psa":{"title":"PSA (prostaatspecifiek antigeen)","short":"PSA is een eiwit dat door prostaatcellen wordt gemaakt; een verhoogde waarde kan wijzen op prostaatkanker, maar ook op prostaatvergroting of ontsteking.","definition":"<p>Het <strong>PSA</strong> is weinig specifiek. Daarom volgt bij een verhoogde waarde eerst een risicocalculator en een MRI, en zo nodig een biopsie. Screening van alle mannen geeft veel overdiagnostiek. Na behandeling van prostaatkanker wordt PSA gebruikt om een recidief op te sporen.</p>","image_url":"","wiki_title":"Prostate-specific antigen","match":"psa|prostaatspecifiek antigeen","option_only":true},"cytonucleaire atypie":{"title":"Kenmerken van maligniteit (histologie)","short":"Kenmerken van een kwaadaardige tumor onder de microscoop zijn atypische kernen, veel (afwijkende) delingsfiguren, infiltratieve groei en uitzaaiing.","definition":"<p>Bij <strong>cytonucleaire atypie</strong> zijn de kernen vergroot, onregelmatig, donker en wisselend van vorm. Alleen infiltratie in het omliggende weefsel en metastasering bewijzen kwaadaardigheid; atypie en mitosen kunnen ook bij een goedaardige of reactieve afwijking voorkomen.</p>","image_url":"","wiki_title":"Nuclear atypia","match":"cytonucleaire atypie|talrijke mitosefiguren|atypie|infiltratie|metastasering","option_only":true},"diverticulosis/itis":{"title":"Diverticulose en diverticulitis","short":"Bij diverticulose zijn er uitstulpingen van het slijmvlies door de wand van het colon; als zo'n divertikel ontsteekt, heet het diverticulitis.","definition":"<p><strong>Diverticulose</strong> komt in westerse landen vooral voor in het sigmoïd, bij ouderen en bij een vezelarm dieet. Diverticulitis geeft pijn linksonder en koorts; complicaties zijn een abces, perforatie en fistels. Divertikels kunnen ook pijnloos een forse bloeding geven.</p>","image_url":"","wiki_title":"Diverticular disease","match":"diverticulosis/itis|diverticulose|diverticulitis|divertikelbloeding in het colon","option_only":true},"fibro-adenoom":{"title":"Fibroadenoom","short":"Een fibroadenoom is een goedaardige, goed beweeglijke knobbel in de borst, vooral bij jonge vrouwen.","definition":"<p>Een <strong>fibroadenoom</strong> bestaat uit klier- en bindweefsel, voelt rond, glad en rubberachtig aan en is goed verschuifbaar. Diagnose met echo en zo nodig een biopt. Verwijderen is meestal niet nodig.</p>","image_url":"","wiki_title":"Fibroadenoma","match":"fibro-adenoom|fibroadenoom","option_only":true},"mastopathie":{"title":"Mastopathie (fibrocysteuze veranderingen)","short":"Mastopathie is een verzamelnaam voor goedaardige veranderingen in het borstweefsel, met knobbeligheid, cysten en pijn die met de cyclus wisselen.","definition":"<p><strong>Mastopathie</strong> komt veel voor tussen 30 en 50 jaar. De meeste vormen geven geen verhoogd risico op borstkanker; alleen proliferatieve vormen met atypie wel.</p>","image_url":"","wiki_title":"Fibrocystic breast changes","match":"mastopathie|fibrocysteuze mastopathie","option_only":true},"cox regressieanalyse":{"title":"Regressieanalyse","short":"Regressieanalyse beschrijft het verband tussen een uitkomst en een of meer determinanten; het type hangt af van de uitkomst.","definition":"<p>Bij een continue uitkomst wordt <strong>lineaire regressie</strong> gebruikt, bij een dichotome uitkomst logistische regressie, en bij tijd tot een gebeurtenis <strong>Cox-regressie</strong> (met hazard ratio's, onder de aanname van proportionele hazards). ANOVA vergelijkt de gemiddelden van meer dan twee groepen.</p>","image_url":"","wiki_title":"Regression analysis","match":"cox regressieanalyse|lineaire regressieanalyse|logistische regressie|variantieanalyse (anova)","option_only":true},"pearson-correlatiecoëfficiënt":{"title":"Correlatiecoëfficiënt","short":"Een correlatiecoëfficiënt (−1 tot +1) geeft aan hoe sterk twee variabelen samenhangen.","definition":"<p>De <strong>Pearson</strong>-coëfficiënt meet een lineair verband tussen normaal verdeelde continue variabelen. De <strong>Spearman</strong>-coëfficiënt gebruikt rangordes en is geschikt bij scheve verdelingen of ordinale data. Correlatie zegt niets over oorzaak en gevolg of over overeenstemming.</p>","image_url":"","wiki_title":"Pearson correlation coefficient","match":"pearson-correlatiecoëfficiënt|spearman-correlatiecoëfficiënt|correlatiecoëfficiënt","option_only":true},"aspergillus spp":{"title":"Aspergillus fumigatus","short":"Aspergillus fumigatus is een schimmel waarvan de sporen overal in de lucht zijn; bij neutropenie kan hij een invasieve longinfectie geven.","definition":"<p><strong><em>Aspergillus</em></strong> kan verschillende ziektebeelden geven: allergische bronchopulmonale aspergillose (bij astma en CF), een aspergilloom (schimmelbal in een bestaande holte) en invasieve aspergillose bij ernstig afweergestoorde patiënten, met invasie van bloedvaten. Diagnostiek met CT, galactomannan en kweek; behandeling met voriconazol.</p>","image_url":"","wiki_title":"Aspergillus fumigatus","match":"aspergillus spp","option_only":true},"lineaire regressieanalyse":{"title":"Regressieanalyse","short":"Regressieanalyse beschrijft het verband tussen een uitkomst en een of meer determinanten; het type hangt af van de uitkomst.","definition":"<p>Bij een continue uitkomst wordt <strong>lineaire regressie</strong> gebruikt, bij een dichotome uitkomst logistische regressie, en bij tijd tot een gebeurtenis <strong>Cox-regressie</strong> (met hazard ratio's, onder de aanname van proportionele hazards). ANOVA vergelijkt de gemiddelden van meer dan twee groepen.</p>","image_url":"","wiki_title":"Regression analysis","match":"lineaire regressieanalyse","option_only":true},"variantieanalyse (anova)":{"title":"Regressieanalyse","short":"Regressieanalyse beschrijft het verband tussen een uitkomst en een of meer determinanten; het type hangt af van de uitkomst.","definition":"<p>Bij een continue uitkomst wordt <strong>lineaire regressie</strong> gebruikt, bij een dichotome uitkomst logistische regressie, en bij tijd tot een gebeurtenis <strong>Cox-regressie</strong> (met hazard ratio's, onder de aanname van proportionele hazards). ANOVA vergelijkt de gemiddelden van meer dan twee groepen.</p>","image_url":"","wiki_title":"Regression analysis","match":"variantieanalyse (anova)","option_only":true},"spearman-correlatiecoëfficiënt":{"title":"Correlatiecoëfficiënt","short":"Een correlatiecoëfficiënt (−1 tot +1) geeft aan hoe sterk twee variabelen samenhangen.","definition":"<p>De <strong>Pearson</strong>-coëfficiënt meet een lineair verband tussen normaal verdeelde continue variabelen. De <strong>Spearman</strong>-coëfficiënt gebruikt rangordes en is geschikt bij scheve verdelingen of ordinale data. Correlatie zegt niets over oorzaak en gevolg of over overeenstemming.</p>","image_url":"","wiki_title":"Pearson correlation coefficient","match":"spearman-correlatiecoëfficiënt","option_only":true},"herpes simplex virus-2":{"title":"Herpes simplexvirus (HSV)","short":"Het herpes simplexvirus veroorzaakt blaasjes op huid en slijmvliezen en blijft daarna latent in sensibele ganglia.","definition":"<p>Er zijn twee typen: <strong>HSV-1</strong> (vooral oraal, koortslip, gingivostomatitis) en <strong>HSV-2</strong> (vooral genitaal), al overlappen ze. Na de primaire infectie blijft het virus latent in sensibele ganglia en kan het reactiveren. Ernstige vormen zijn herpesencefalitis, keratitis, eczema herpeticum en neonatale herpes. Behandeling met (val)aciclovir.</p>","image_url":"","wiki_title":"Herpes simplex virus","match":"herpes simplex virus-2","option_only":true},"stafylokok":{"title":"Staphylococcus aureus","short":"S. aureus is een grampositieve kok in trosjes, coagulasepositief, die huid- en wondinfecties, abcessen en ernstige systemische infecties veroorzaakt.","definition":"<p><strong><em>Staphylococcus aureus</em></strong> is een grampositieve kok die in trosjes groeit en <em>coagulase-positief</em> is (onderscheid met andere stafylokokken). Ongeveer een derde van de mensen draagt hem in de neus.</p><p>Hij veroorzaakt huid- en wekedeleninfecties (impetigo, furunkels, abcessen, wondinfecties), maar ook osteomyelitis, septische artritis, endocarditis en sepsis. Via toxines kan hij voedselvergiftiging en het toxischeshocksyndroom veroorzaken. MRSA is een methicillineresistente variant.</p>","image_url":"","wiki_title":"Staphylococcus aureus","match":"stafylokok","option_only":true},"appendicits":{"title":"Appendicitis","short":"Appendicitis is een ontsteking van de appendix, met buikpijn die vaak rond de navel begint en naar rechtsonder trekt.","definition":"<p>Bij <strong>appendicitis</strong> raakt het lumen van de appendix afgesloten (bijv. door een fecoliet of lymfoïde hyperplasie), waarna ontsteking en infectie volgen. Klachten: pijn eerst rond de navel, later rechtsonder (McBurney), misselijkheid, koorts en lokale peritoneale prikkeling. Zonder behandeling kan perforatie optreden. Diagnose met echo en/of CT; behandeling meestal appendectomie.</p>","image_url":"","wiki_title":"Appendicitis","match":"appendicits","option_only":true},"gastro-enteritis, mogelijk het norovirus":{"title":"Norovirus","short":"Norovirus is een zeer besmettelijk RNA-virus dat acute gastro-enteritis veroorzaakt met plotseling braken en diarree, vaak in uitbraken.","definition":"<p>Het <strong>norovirus</strong> is een niet-omhuld RNA-virus (calicivirus). Er zijn maar weinig deeltjes nodig voor infectie en het overleeft lang in de omgeving.</p><p>Het veroorzaakt acute gastro-enteritis met plotseling braken, waterige diarree en buikkrampen, die 1 à 3 dagen duurt. Uitbraken komen vooral voor in verpleeghuizen, ziekenhuizen en op cruiseschepen; handhygiëne is de belangrijkste maatregel.</p>","image_url":"","wiki_title":"Norovirus","match":"gastro-enteritis, mogelijk het norovirus","option_only":true},"colorectaal carcinoom":{"title":"Colorectaal carcinoom","short":"Het colorectaal carcinoom is een adenocarcinoom van de dikke darm, meestal ontstaan uit een adenoom.","definition":"<p>Een tumor <strong>links</strong> geeft vaak een veranderd ontlastingspatroon en bloed bij de ontlasting; een tumor <strong>rechts</strong> vaker een ijzergebreksanemie. Risicofactoren: leeftijd, familie, IBD, Lynch-syndroom en FAP. In Nederland is er een bevolkingsonderzoek met een FIT-test.</p>","image_url":"","wiki_title":"Colorectal cancer","match":"colorectaal carcinoom|darmkanker|coloncarcinoom|rectumcarcinoom","option_only":true}};
